import * as THREE from 'three';

/**
 * Seeded PRNG (mulberry32).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Generate `count` deterministic tree positions spread over an
 * `area` x `area` square centered at the origin (y = 0).
 *
 * @returns {THREE.Vector3[]}
 */
export function planForest({ seed, count = 300, area = 100 } = {}) {
  const rand = mulberry32(seed);
  const positions = [];
  for (let i = 0; i < count; i++) {
    positions.push(
      new THREE.Vector3(
        (rand() - 0.5) * area,
        0,
        (rand() - 0.5) * area,
      ),
    );
  }
  return positions;
}

/**
 * Assign position indices to LOD buckets by distance to the camera.
 *
 *   high: distance <  cuts[0]
 *   mid:  cuts[0] <= distance < cuts[1]
 *   low:  distance >= cuts[1]
 *
 * @param {THREE.Vector3[]} positions
 * @param {THREE.Camera|THREE.Vector3} camera camera (uses .position) or a point
 * @param {[number, number]} cuts
 * @returns {{high: number[], mid: number[], low: number[]}}
 */
export function assignBuckets(positions, camera, cuts = [25, 60]) {
  const [nearCut, farCut] = cuts;
  const origin = camera.isVector3 ? camera : camera.position;
  const high = [];
  const mid = [];
  const low = [];
  for (let i = 0; i < positions.length; i++) {
    const d = origin.distanceTo(positions[i]);
    if (d < nearCut) high.push(i);
    else if (d < farCut) mid.push(i);
    else low.push(i);
  }
  return { high, mid, low };
}

const DETAIL_BY_BUCKET = { high: 2, mid: 1, low: 0 };

/**
 * Build one InstancedMesh per bucket. Geometry detail decreases from
 * high -> low so distant trees are cheap.
 *
 * @param {THREE.Vector3[]} positions
 * @param {{high: number[], mid: number[], low: number[]}} buckets
 * @returns {{high: THREE.InstancedMesh, mid: THREE.InstancedMesh, low: THREE.InstancedMesh}}
 */
export function buildBucketMeshes(positions, buckets) {
  const geometryFor = (detail) => new THREE.IcosahedronGeometry(1, detail);
  const material = new THREE.MeshLambertMaterial({ color: 0x2e7d32 });
  const matrix = new THREE.Matrix4();

  const meshes = {};
  for (const bucket of ['high', 'mid', 'low']) {
    const indices = buckets[bucket];
    const mesh = new THREE.InstancedMesh(
      geometryFor(DETAIL_BY_BUCKET[bucket]),
      material,
      indices.length,
    );
    indices.forEach((index, slot) => {
      mesh.setMatrixAt(slot, matrix.makeTranslation(positions[index]));
    });
    mesh.instanceMatrix.needsUpdate = true;
    meshes[bucket] = mesh;
  }
  return meshes;
}

