import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { planForest, assignBuckets, buildBucketMeshes } from '../src/lodforest.js';

const COUNT = 300;
const AREA = 100;
const SEED = 1337;
const CUTS = [25, 60];

describe('planForest', () => {
  it('generates the requested number of positions deterministically', () => {
    const a = planForest({ seed: SEED, count: COUNT, area: AREA });
    const b = planForest({ seed: SEED, count: COUNT, area: AREA });
    expect(a).toHaveLength(COUNT);
    expect(a.map((p) => p.x)).toEqual(b.map((p) => p.x));
    expect(a.map((p) => p.z)).toEqual(b.map((p) => p.z));
    for (const p of a) {
      expect(Math.abs(p.x)).toBeLessThanOrEqual(AREA / 2);
      expect(Math.abs(p.z)).toBeLessThanOrEqual(AREA / 2);
    }
  });
});

describe('assignBuckets', () => {
  const positions = planForest({ seed: SEED, count: COUNT, area: AREA });

  function bucketsFor(camPos) {
    const camera = new THREE.PerspectiveCamera();
    camera.position.copy(camPos);
    return assignBuckets(positions, camera, CUTS);
  }

  it('bucket index arrays are disjoint and sizes sum to count', () => {
    const { high, mid, low } = bucketsFor(new THREE.Vector3(0, 2, 0));
    const all = [...high, ...mid, ...low];
    expect(all).toHaveLength(COUNT);
    expect(new Set(all).size).toBe(COUNT); // no index appears twice
    expect(high.length + mid.length + low.length).toBe(COUNT);
  });

  it('a centered camera sees strictly more high trees than one far outside', () => {
    const centerBuckets = bucketsFor(new THREE.Vector3(0, 0, 0));
    const farBuckets = bucketsFor(new THREE.Vector3(5000, 0, 5000));
    expect(centerBuckets.high.length).toBeGreaterThan(0);
    expect(centerBuckets.high.length).toBeGreaterThan(farBuckets.high.length);
    expect(farBuckets.high.length).toBe(0);
  });

  it('every tree in a bucket satisfies its distance definition', () => {
    const camPos = new THREE.Vector3(12, 3, -7);
    const { high, mid, low } = bucketsFor(camPos);
    const dist = (i) => camPos.distanceTo(positions[i]);

    for (const i of high) expect(dist(i)).toBeLessThan(CUTS[0]);
    for (const i of mid) {
      expect(dist(i)).toBeGreaterThanOrEqual(CUTS[0]);
      expect(dist(i)).toBeLessThan(CUTS[1]);
    }
    for (const i of low) expect(dist(i)).toBeGreaterThanOrEqual(CUTS[1]);
  });

  it('moving the camera changes the bucket assignment', () => {
    const before = bucketsFor(new THREE.Vector3(0, 5, 10));
    const after = bucketsFor(new THREE.Vector3(-40, 5, 40));
    const key = (b) => `${b.high.join(',')}|${b.mid.join(',')}|${b.low.join(',')}`;
    expect(key(after)).not.toBe(key(before));
  });
});

describe('buildBucketMeshes', () => {
  it('creates InstancedMeshes whose counts match bucket sizes at correct positions', () => {
    const positions = planForest({ seed: SEED, count: COUNT, area: AREA });
    const camera = new THREE.PerspectiveCamera();
    camera.position.set(0, 4, 0);
    const buckets = assignBuckets(positions, camera, CUTS);
    const meshes = buildBucketMeshes(positions, buckets);

    for (const name of ['high', 'mid', 'low']) {
      const mesh = meshes[name];
      expect(mesh).toBeInstanceOf(THREE.InstancedMesh);
      expect(mesh.count).toBe(buckets[name].length);

      // each instance's translation must place a tree at its position
      const matrix = new THREE.Matrix4();
      const pos = new THREE.Vector3();
      const placed = [];
      for (let slot = 0; slot < mesh.count; slot++) {
        mesh.getMatrixAt(slot, matrix);
        pos.setFromMatrixPosition(matrix);
        placed.push(pos.clone());
      }
      const expected = buckets[name].map((i) => positions[i]);
      for (const p of expected) {
        expect(
          placed.some((q) => q.distanceToSquared(p) < 1e-8),
        ).toBe(true);
      }
    }
  });
});

